DO $qa$
DECLARE m uuid:=gen_random_uuid(); u uuid:=gen_random_uuid(); x uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); g bigint; rev bigint; cr bigint; checks int:=0; denied boolean; target bigint:=9223372036854775807; snapshot jsonb; current_count int;
BEGIN
 BEGIN
 INSERT INTO auth.users(id) VALUES(m),(u),(x);
 INSERT INTO public.ff_profiles(user_id,display_name,role,active) VALUES(m,'A09 QA manager','manager',true),(u,'A09 QA cashier','cashier',true),(x,'A09 QA no grant','cashier',true) ON CONFLICT(user_id) DO UPDATE SET role=excluded.role,active=true;
 INSERT INTO public.ff_branches(id,code,name) VALUES(b,'qa-a09-'||b,'A09 QA branch');
 INSERT INTO public.ff_user_branches(user_id,branch_id) VALUES(u,b),(x,b);
 PERFORM set_config('request.jwt.claim.sub',m::text,true);
 SET LOCAL ROLE authenticated;
 g:=public.ff_a09_set_grant(u,b,'cashier',ARRAY['view','edit'],now()-interval '1 minute',now()+interval '1 hour',ARRAY['text','colors']);
 rev:=public.ff_a07_named_design('cashier','cashier',b,'mobile','D01','','labels','QA design','',NULL,'{}');
 cr:=public.ff_content_create_draft('cashier.title','cashier',b,'QA content');
 PERFORM public.ff82_revoke_grant(g);
 RESET ROLE;
 SELECT jsonb_build_object('design',(SELECT count(*) FROM public.ff_ui_versions),'content',(SELECT count(*) FROM public.ff_content_versions),'trial',(SELECT count(*) FROM public.ff_ui_trials),'grant',(SELECT count(*) FROM public.ff82_content_grants)) INTO snapshot;
 PERFORM set_config('request.jwt.claim.sub',u::text,true);
 PERFORM set_config('request.method','POST',true);
 SET LOCAL ROLE authenticated;
 PERFORM public.ff_ui_publish(rev); IF current_setting('response.status',true)<>'403' THEN RAISE EXCEPTION 'design publish status'; END IF; checks:=checks+1;
 PERFORM set_config('response.status','200',true);
 IF public.ff_ui_rollback(rev) IS NOT NULL OR current_setting('response.status',true)<>'403' THEN RAISE EXCEPTION 'design restore status'; END IF;checks:=checks+1;
 PERFORM set_config('response.status','200',true);
 IF public.ff_ui_control_trial(rev,ARRAY[u],1) IS NOT NULL OR current_setting('response.status',true)<>'403' THEN RAISE EXCEPTION 'trial status'; END IF;checks:=checks+1;
 PERFORM set_config('response.status','200',true);
 PERFORM public.ff_content_publish(cr);IF current_setting('response.status',true)<>'403' THEN RAISE EXCEPTION 'content publish status'; END IF;checks:=checks+1;
 PERFORM set_config('response.status','200',true);
 IF public.ff_content_create_draft('cashier.title','cashier',b,NULL) IS NOT NULL OR current_setting('response.status',true)<>'403' THEN RAISE EXCEPTION 'content restore status'; END IF;checks:=checks+1;
 PERFORM set_config('response.status','200',true);
 IF public.ff_ui_save_draft('cashier',b,'mobile','D01','','labels',rev) IS NOT NULL OR current_setting('response.status',true)<>'403' THEN RAISE EXCEPTION 'design restore draft status'; END IF;checks:=checks+1;
 PERFORM set_config('response.status','200',true);
 IF public.ff_a07_named_design('cashier','cashier',b,'mobile','D01','','labels','QA bad','',NULL,'{}') IS NOT NULL OR current_setting('response.status',true)<>'403' THEN RAISE EXCEPTION 'named design status'; END IF;checks:=checks+1;
 PERFORM set_config('response.status','200',true);
 IF public.ff_ui_named_draft('cashier',b,'mobile','D01','','labels','QA bad','') IS NOT NULL OR current_setting('response.status',true)<>'403' THEN RAISE EXCEPTION 'named draft status'; END IF;checks:=checks+1;
 PERFORM set_config('response.status','200',true);
 IF public.ff81_named_card_draft('cashier',b,'mobile','D01','','labels','QA bad','',NULL) IS NOT NULL OR current_setting('response.status',true)<>'403' THEN RAISE EXCEPTION 'card draft status'; END IF;checks:=checks+1;
 PERFORM set_config('response.status','200',true);
 IF public.ff_a09_set_grant(u,b,'cashier',ARRAY['edit'],now(),now()+interval '1 hour',ARRAY['text']) IS NOT NULL OR current_setting('response.status',true)<>'403' THEN RAISE EXCEPTION 'grant escalation status'; END IF;checks:=checks+1;
 PERFORM set_config('response.status','200',true);
 IF public.ff82_set_grant(u,b,'cashier',ARRAY['edit'],now(),now()+interval '1 hour') IS NOT NULL OR current_setting('response.status',true)<>'403' THEN RAISE EXCEPTION 'legacy grant escalation status'; END IF;checks:=checks+1;
 PERFORM set_config('response.status','200',true);
 IF public.ff82_revoke_grant(g) IS DISTINCT FROM false OR current_setting('response.status',true)<>'403' THEN RAISE EXCEPTION 'grant revoke status'; END IF;checks:=checks+1;
 PERFORM set_config('response.status','200',true);
 PERFORM public.ff_ui_publish(target);IF current_setting('response.status',true)<>'403' THEN RAISE EXCEPTION 'missing target status';END IF;checks:=checks+1;
 IF EXISTS(SELECT FROM public.ff82_manager_audit()) THEN RAISE EXCEPTION 'non-manager audit disclosure'; END IF;checks:=checks+1;
 RESET ROLE;
 IF (SELECT count(*) FROM public.ff82_content_audit WHERE actor_id=u AND outcome='denied' AND reason='manager_only:revoked' AND effect='no_change' AND grant_id=g)<>13 THEN RAISE EXCEPTION 'missing durable audit rows';END IF;checks:=checks+1;
 IF NOT EXISTS(SELECT FROM public.ff82_content_audit WHERE actor_id=u AND attempted_revision=target AND design_revision IS NULL AND revision_id IS NULL) THEN RAISE EXCEPTION 'untrusted target FK leak';END IF;checks:=checks+1;
 IF snapshot IS DISTINCT FROM jsonb_build_object('design',(SELECT count(*) FROM public.ff_ui_versions),'content',(SELECT count(*) FROM public.ff_content_versions),'trial',(SELECT count(*) FROM public.ff_ui_trials),'grant',(SELECT count(*) FROM public.ff82_content_grants)) OR EXISTS(SELECT FROM public.ff_ui_versions WHERE id=rev AND published_at IS NOT NULL) OR EXISTS(SELECT FROM public.ff_content_versions WHERE id=cr AND published_at IS NOT NULL) THEN RAISE EXCEPTION 'denied operation altered state';END IF;checks:=checks+1;
 UPDATE public.ff82_content_grants SET revoked_at=NULL,revoked_by=NULL,ends_at=clock_timestamp()-interval '1 second' WHERE id=g;
 SET LOCAL ROLE authenticated;
 PERFORM set_config('response.status','200',true);PERFORM public.ff_ui_publish(rev);
 IF current_setting('response.status',true)<>'403' THEN RAISE EXCEPTION 'expired publish';END IF;checks:=checks+1;
 RESET ROLE;
 IF NOT EXISTS(SELECT FROM public.ff82_content_audit WHERE actor_id=u AND reason='manager_only:expired' AND action='design_publish' AND effect='no_change') THEN RAISE EXCEPTION 'expiry reason';END IF;checks:=checks+1;
 PERFORM set_config('request.jwt.claim.sub',x::text,true);
 SET LOCAL ROLE authenticated;
 PERFORM set_config('response.status','200',true);PERFORM public.ff_ui_publish(rev);
 IF current_setting('response.status',true)<>'403' THEN RAISE EXCEPTION 'no grant denied';END IF;checks:=checks+1;
 RESET ROLE;
 IF NOT EXISTS(SELECT FROM public.ff82_content_audit WHERE actor_id=x AND grant_id IS NULL AND reason='manager_only:no_grant') THEN RAISE EXCEPTION 'no grant audit';END IF;checks:=checks+1;
 PERFORM set_config('request.method','',true);PERFORM set_config('request.jwt.claim.sub',u::text,true);
 SET LOCAL ROLE authenticated;
 denied:=false;BEGIN PERFORM public.ff_ui_publish(rev);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'SQL exception compatibility';END IF;checks:=checks+1;
 RESET ROLE;
 PERFORM set_config('request.jwt.claim.sub',m::text,true);
 SET LOCAL ROLE authenticated;
 IF (SELECT count(*) FROM public.ff82_manager_audit() WHERE actor_id=u AND effect='no_change')<>14 THEN RAISE EXCEPTION 'manager audit visibility';END IF;checks:=checks+1;
 PERFORM public.ff_ui_publish(rev);PERFORM public.ff_content_publish(cr);
 RESET ROLE;
 IF NOT EXISTS(SELECT FROM public.ff_ui_versions WHERE id=rev AND published_by=m AND published_at IS NOT NULL) OR NOT EXISTS(SELECT FROM public.ff_content_versions WHERE id=cr AND published_by=m AND published_at IS NOT NULL) THEN RAISE EXCEPTION 'manager release regression';END IF;checks:=checks+1;
 IF has_function_privilege('authenticated','ff_private.a09_reject_manager(text,bigint,text,text)','EXECUTE') OR has_table_privilege('authenticated','public.ff82_content_audit','INSERT') OR has_function_privilege('anon','public.ff_ui_publish(bigint)','EXECUTE') THEN RAISE EXCEPTION 'privilege escalation';END IF;checks:=checks+1;
 RAISE EXCEPTION 'QA rollback' USING ERRCODE='ZQ039';
 EXCEPTION WHEN SQLSTATE 'ZQ039' THEN NULL;END;
 IF checks<>25 OR EXISTS(SELECT FROM public.ff_branches WHERE id=b) OR EXISTS(SELECT FROM public.ff82_content_audit WHERE actor_id IN(m,u,x)) THEN RAISE EXCEPTION 'Incomplete QA rollback %',checks;END IF;
END $qa$;
SELECT 'PASS A09: 25 manager denial audit, status, expiry, no-change, authorized publication and rollback assertions' result;